<?php
/* Phase 312: repair two files using a unique path; old attachment is removed before writing. */
add_action('init',function(){
if(get_option('bhc_catalog_image_emersun_remediation_repair_v312'))return;
@ini_set('memory_limit','768M');$map=['BFN27D502'=>'emersun-bfn27d502-source.png','FN20D'=>'emersun-fn20d-source.png'];$result=[];
foreach($map as $model=>$srcname){$ids=get_posts(['post_type'=>'product','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_bhc_model','meta_value'=>$model]);$id=$ids?(int)$ids[0]:0;$src=__DIR__.'/'.$srcname;$rel='bhc-image-references/emersun-'.sanitize_title($model).'-repair-v312.png';$file=ABSPATH.'wp-content/uploads/'.$rel;$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$ok=false;$aid=0;if($id&&is_readable($src)){$im=@imagecreatefrompng($src);if($im){wp_mkdir_p(dirname($file));$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$c=imagecreatetruecolor($nw,$nh);imagealphablending($c,false);imagesavealpha($c,true);$z=imagecolorallocatealpha($c,0,0,0,127);imagefill($c,0,0,$z);imagecopyresampled($c,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($c,$file,6);imagedestroy($c);imagedestroy($im);$ok=is_readable($file);}}if($ok){$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Emersun '.$model.' repaired 4K transparent','post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$rel);$q=@getimagesize($file);wp_update_attachment_metadata($aid,['width'=>$q[0]??4096,'height'=>$q[1]??4096,'file'=>$rel,'sizes'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_featured_verified','yes');}}$result[$model]=['id'=>$id,'ok'=>$ok,'attachment'=>$aid,'exists'=>is_readable($file)];}
update_option('bhc_catalog_image_emersun_remediation_repair_v312',['result'=>$result,'at'=>current_time('mysql')],false);
},312);
